import * as THREE from 'three';

import dayMapUrl from '../assets/planets/world-day.jpg';
import normalMapUrl from '../assets/planets/world-normal.jpg';
import nightMapUrl from '../assets/planets/world-night.jpg';
import cloudsMapUrl from '../assets/planets/world-clouds.png';
import surfaceMapUrl from '../assets/planets/world-surface.png';

/*
 * The Half-Made World, as one planet.
 *
 * The surface maps are generated by scripts/generate_planet_textures.py: a
 * real equirectangular world with oceans, ice caps, mountain relief and
 * weather, where the Human, Angel and Demon realms are continents and the
 * Hidden Realm holds the ground in the middle of their meeting.
 *
 * The planet is a real sphere mesh, lit by a single sun so the terminator
 * sweeps across it, and it turns on its own tilted axis - a day and a night,
 * not a spin. The dark side keeps the emissive map: settlement lights in the
 * Human Realm, lava in the Demon Realm, rift-light in the Hidden Realm.
 */

/** Direction to the sun, in world space. Fixed, so the terminator moves. */
const SUN_DIR = new THREE.Vector3(-0.22, 0.3, 0.93).normalize();

/**
 * How far the planet sits from the camera, in world units. The camera looks
 * straight at the world, and the view is offset to place it in the upper
 * right, so the map on the globe always faces us the way it is painted.
 */
export const PLANET_DISTANCE = 14.35;

/** The camera's field of view. A longer lens keeps the world undistorted. */
export const PLANET_FOV = 30;

/** The planet's axial tilt, in radians (about 23 degrees). */
const AXIAL_TILT = 0.41;

/** How long one turn of the world takes, in seconds. */
const SPIN_PERIOD = 300;

const ATMOSPHERE_VERTEX = `
varying vec3 vNormalW;
varying vec3 vViewW;
void main() {
  vec4 worldPos = modelMatrix * vec4(position, 1.0);
  vNormalW = normalize(mat3(modelMatrix) * normal);
  vViewW = normalize(cameraPosition - worldPos.xyz);
  gl_Position = projectionMatrix * viewMatrix * worldPos;
}
`;

const ATMOSPHERE_FRAGMENT = `
uniform vec3 uSunDir;
uniform vec3 uColor;
varying vec3 vNormalW;
varying vec3 vViewW;
void main() {
  vec3 n = normalize(vNormalW);
  float rim = pow(1.0 - clamp(dot(n, normalize(vViewW)), 0.0, 1.0), 3.2);
  float sun = clamp(dot(n, normalize(uSunDir)) * 0.85 + 0.3, 0.0, 1.0);
  float a = rim * sun;
  gl_FragColor = vec4(uColor, a);
}
`;

export interface WorldPlanet {
  /** The group that carries the planet. It sits at the world's centre. */
  root: THREE.Group;
  /** The group that turns on the planet's axis. */
  spin: THREE.Group;
  /** The cloud layer, which drifts a little faster than the ground. */
  clouds: THREE.Mesh;
  /** The sun that lights the world. */
  sun: THREE.DirectionalLight;
  /** Turns the world to the given elapsed time, in seconds. */
  update(elapsed: number): void;
  /** Releases every GPU resource the planet holds. */
  dispose(): void;
}

function loadTexture(url: string, loader: THREE.TextureLoader, srgb: boolean): THREE.Texture {
  const texture = loader.load(url);
  if (srgb) texture.colorSpace = THREE.SRGBColorSpace;
  texture.anisotropy = 4;
  return texture;
}

export function createWorldPlanet(): WorldPlanet {
  const group = new THREE.Group();
  const spin = new THREE.Group();
  const tilt = new THREE.Group();
  tilt.rotation.x = AXIAL_TILT;
  tilt.add(spin);
  group.add(tilt);

  const manager = new THREE.LoadingManager();
  manager.onError = (url) => {
    console.warn('Planet texture failed to load:', url);
  };
  const loader = new THREE.TextureLoader(manager);

  const day = loadTexture(dayMapUrl, loader, true);
  const normal = loadTexture(normalMapUrl, loader, false);
  const night = loadTexture(nightMapUrl, loader, true);
  const clouds = loadTexture(cloudsMapUrl, loader, true);
  const surface = loadTexture(surfaceMapUrl, loader, false);

  const groundMaterial = new THREE.MeshStandardMaterial({
    map: day,
    normalMap: normal,
    normalScale: new THREE.Vector2(0.6, 0.6),
    roughnessMap: surface,
    metalnessMap: surface,
    emissiveMap: night,
    emissive: new THREE.Color(0xffffff),
    emissiveIntensity: 2.0,
    roughness: 1,
    metalness: 1,
  });

  // The emissive map is night-side light: it must not wash out the day side.
  groundMaterial.onBeforeCompile = (shader) => {
    shader.uniforms.uSunDir = { value: SUN_DIR.clone() };
    shader.fragmentShader = shader.fragmentShader
      .replace(
        'void main() {',
        'uniform vec3 uSunDir;\nvoid main() {'
      )
      .replace(
        '#include <emissivemap_fragment>',
        `#include <emissivemap_fragment>
         vec3 sunView = normalize((viewMatrix * vec4(uSunDir, 0.0)).xyz);
         float nightSide = smoothstep(0.35, -0.15, dot(normalize(vNormal), sunView));
         totalEmissiveRadiance *= nightSide;`
      );
  };

  const ground = new THREE.Mesh(new THREE.SphereGeometry(1, 128, 96), groundMaterial);
  spin.add(ground);

  const cloudMaterial = new THREE.MeshStandardMaterial({
    map: clouds,
    transparent: true,
    depthWrite: false,
    roughness: 1,
    metalness: 0,
  });
  const cloudMesh = new THREE.Mesh(new THREE.SphereGeometry(1.012, 96, 64), cloudMaterial);
  spin.add(cloudMesh);

  // A soft halo just outside the world, lit from the sun side.
  const atmosphere = new THREE.Mesh(
    new THREE.SphereGeometry(1.075, 64, 48),
    new THREE.ShaderMaterial({
      vertexShader: ATMOSPHERE_VERTEX,
      fragmentShader: ATMOSPHERE_FRAGMENT,
      uniforms: {
        uSunDir: { value: SUN_DIR.clone() },
        uColor: { value: new THREE.Color(0x6fa8d6) },
      },
      transparent: true,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      side: THREE.BackSide,
    })
  );
  tilt.add(atmosphere);

  const sun = new THREE.DirectionalLight(0xfff4e2, 3.1);
  const target = new THREE.Object3D();
  group.add(sun, target);
  sun.target = target;
  sun.position.copy(SUN_DIR).multiplyScalar(20);

  const planet: WorldPlanet = {
    root: group,
    spin,
    clouds: cloudMesh,
    sun,
    update(elapsed: number) {
      spin.rotation.y = (elapsed / SPIN_PERIOD) * Math.PI * 2;
      // Weather runs a little ahead of the ground.
      cloudMesh.rotation.y = (elapsed / (SPIN_PERIOD * 0.88)) * Math.PI * 2;
    },
    dispose() {
      ground.geometry.dispose();
      groundMaterial.dispose();
      cloudMesh.geometry.dispose();
      cloudMaterial.dispose();
      atmosphere.geometry.dispose();
      (atmosphere.material as THREE.Material).dispose();
      for (const texture of [day, normal, night, clouds, surface]) texture.dispose();
    },
  };

  return planet;
}
